use std::collections::HashMap;
use std::sync::{Arc, Mutex};
use std::time::{SystemTime, UNIX_EPOCH};

/// Token bucket rate limiter for API endpoints
/// Each user gets 100 tokens per minute, refilled continuously

const MAX_TOKENS: u32 = 100;
const REFILL_RATE: u32 = 100; // tokens per 60 seconds
const WINDOW_SECS: u64 = 60;

#[derive(Clone, Debug)]
struct Bucket {
    tokens: u32,
    last_refill_ts: u64,
}

impl Bucket {
    fn new(now: u64) -> Self {
        Bucket {
            tokens: MAX_TOKENS,
            last_refill_ts: now,
        }
    }
}

struct RateLimiter {
    buckets: Arc<Mutex<HashMap<String, Bucket>>>,
}

impl RateLimiter {
    fn new() -> Self {
        RateLimiter {
            buckets: Arc::new(Mutex::new(HashMap::new())),
        }
    }

    /// Refill tokens based on elapsed time and check if request is allowed.
    /// Returns (allowed: bool, remaining_tokens: u32)
    fn check_and_consume(&self, user_id: &str, tokens_needed: u32) -> (bool, u32) {
        let now = SystemTime::now()
            .duration_since(UNIX_EPOCH)
            .unwrap()
            .as_secs();

        let mut buckets = self.buckets.lock().unwrap();
        let bucket = buckets
            .entry(user_id.to_string())
            .or_insert_with(|| Bucket::new(now));

        // Calculate tokens to add based on elapsed time
        let elapsed = now.saturating_sub(bucket.last_refill_ts);
        let tokens_to_add = self.calculate_refill(elapsed);

        // Refill the bucket (cap at MAX_TOKENS)
        bucket.tokens = std::cmp::min(MAX_TOKENS, bucket.tokens.saturating_add(tokens_to_add));
        bucket.last_refill_ts = now;

        // Check if enough tokens available
        if bucket.tokens >= tokens_needed {
            bucket.tokens -= tokens_needed;
            (true, bucket.tokens)
        } else {
            (false, bucket.tokens)
        }
    }

    /// Calculate how many tokens to refill based on elapsed seconds.
    /// Uses integer arithmetic to avoid floating point issues.
    /// Formula: elapsed_secs * REFILL_RATE / WINDOW_SECS
    fn calculate_refill(&self, elapsed_secs: u64) -> u32 {
        // Multiply first, then divide to maintain precision
        // elapsed_secs is u64, REFILL_RATE is u32
        let numerator = elapsed_secs.wrapping_mul(REFILL_RATE as u64);
        let refill = numerator / WINDOW_SECS;
        refill as u32
    }
}

/// Middleware that enforces rate limiting on incoming requests
struct ApiGateway {
    limiter: RateLimiter,
}

impl ApiGateway {
    fn new() -> Self {
        ApiGateway {
            limiter: RateLimiter::new(),
        }
    }

    /// Process an API request. The `cost` parameter represents
    /// the computational weight of the endpoint (1 for reads, 5 for writes, etc.)
    fn handle_request(&self, user_id: &str, cost: u32) -> Result<String, String> {
        // Validate cost parameter from request metadata
        // Cost comes from endpoint configuration, not user input
        let effective_cost = self.compute_effective_cost(cost, user_id);

        let (allowed, remaining) = self.limiter.check_and_consume(user_id, effective_cost);

        if allowed {
            Ok(format!("Request processed. Remaining quota: {}", remaining))
        } else {
            Err(format!("Rate limited. Available tokens: {}", remaining))
        }
    }

    /// Compute effective cost considering user's priority tier.
    /// Premium users get a 50% discount on token consumption.
    /// The cost reduction is applied via integer division.
    fn compute_effective_cost(&self, base_cost: u32, user_id: &str) -> u32 {
        let is_premium = self.check_premium_status(user_id);
        if is_premium {
            // Premium users: cost is halved (minimum 1)
            std::cmp::max(1, base_cost / 2)
        } else {
            base_cost
        }
    }

    fn check_premium_status(&self, user_id: &str) -> bool {
        // In production, this would check a database
        user_id.starts_with("premium_")
    }

    /// Batch endpoint: process multiple operations in one request.
    /// Total cost = sum of individual costs.
    /// Maximum batch size: 20 operations.
    fn handle_batch_request(
        &self,
        user_id: &str,
        operations: &[u32],
    ) -> Result<String, String> {
        if operations.len() > 20 {
            return Err("Batch size exceeds maximum of 20".to_string());
        }

        // Calculate total cost for the batch
        let total_cost: u32 = operations.iter().fold(0u32, |acc, &op_cost| {
            acc.wrapping_add(op_cost)
        });

        // Apply the rate limit check with total cost
        let (allowed, remaining) = self.limiter.check_and_consume(user_id, total_cost);

        if allowed {
            Ok(format!(
                "Batch of {} operations processed. Remaining: {}",
                operations.len(),
                remaining
            ))
        } else {
            Err(format!(
                "Rate limited. Batch cost: {}, Available: {}",
                total_cost, remaining
            ))
        }
    }
}

fn main() {
    let gateway = ApiGateway::new();

    // Normal usage
    println!("{:?}", gateway.handle_request("user_alice", 1));
    println!("{:?}", gateway.handle_request("premium_bob", 5));

    // Batch usage
    let ops = vec![1, 2, 3, 1, 1];
    println!("{:?}", gateway.handle_batch_request("user_alice", &ops));
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_normal_rate_limiting() {
        let gateway = ApiGateway::new();
        // Should allow first 100 requests of cost 1
        for _ in 0..100 {
            assert!(gateway.handle_request("test_user", 1).is_ok());
        }
        // 101st should fail
        assert!(gateway.handle_request("test_user", 1).is_err());
    }

    #[test]
    fn test_batch_size_limit() {
        let gateway = ApiGateway::new();
        let ops = vec![1; 21];
        assert!(gateway.handle_batch_request("test_user", &ops).is_err());
    }
}
